import sys

def max_nice_staircases(x):
    n = 0
    count = 0
    while True:
        n += 1
        cells_required = (n * (n + 1)) // 2
        if cells_required > x:
            break
        if x % cells_required == 0:
            count += 1
        x -= cells_required
    return count

def main():
    t = int(sys.stdin.readline().strip())
    results = []
    for _ in range(t):
        x = int(sys.stdin.readline().strip())
        results.append(max_nice_staircases(x))
    for result in results:
        print(result)

if __name__ == "__main__":
    main()
